static void center(int y,const char*s,uint16_t c,int font){text((240-text_width(s,font))/2,y,s,c,font);}
static void screen(void){uint16_t ac=RGB(164,191,255);clear(RGB(8,15,32));center(8,"GLORY PAD 2.2",ac,FONT_SMALL);center(35,names[preset],WHITE,FONT_SMALL);center(75,notes[root],WHITE,FONT_BIG);center(120,modes[mode],ac,FONT_SMALL);center(145,playing?"PAD ACTIVE":"STANDBY",ac,FONT_SMALL);const char *labels0[]={"REVERB","SHIMMER","CUTOFF","CHORUS"};const char *labels1[]={"LEVEL","FADE","DECAY","MODE"};const char *labels2[]={"FLOW","DEPTH","CYCLE","MODE"};int vals0[]={verb,shimmer,cutoff,chorus},vals1[]={level,fade,decay,mode},vals2[]={flow,hdepth,hrate,mode};char buf[12];for(int k=0;k<4;k++){const char *lab=page==2?labels2[k]:page?labels1[k]:labels0[k];int x=k*60;format_int(buf,page==2?vals2[k]:page?vals1[k]:vals0[k]);text(x+(60-text_width(lab,FONT_SMALL))/2,190,lab,ac,FONT_SMALL);text(x+(60-text_width(buf,FONT_SMALL))/2,210,buf,WHITE,FONT_SMALL);}}
