void loop(void){int changed=0;for(int k=0;k<KEY_COUNT;k++)if(key_pressed(k)){root=(KEY_FIRST_NOTE+k)%12;playing=1;changed=1;}uint8_t st,a,b;while(midi_read(&st,&a,&b))if((st&0xf0)==0x90&&b){root=a%12;playing=1;changed=1;}int d=encoder(ENC_SELECT);if(d){root=wrap(root+d,12);changed=1;}d=encoder(ENC_PRESETS);if(d){preset=wrap(preset+d,10);changed=1;}if(button_pressed(BTN_PLAY)){playing=!playing;changed=1;}if(button_pressed(BTN_HOME)){page=(page+1)%3;changed=1;}for(int k=0;k<4;k++){d=encoder(ENC_KNOB1+k);if(!d)continue;volatile int *p;if(!page){p=k==0?&verb:k==1?&shimmer:k==2?&cutoff:&chorus;*p=clamp(*p+d,0,127);}else if(k==3)mode=wrap(mode+d,7);else if(page==2){p=k==0?&flow:k==1?&hdepth:&hrate;*p=clamp(*p+d,k==2?6:0,k==2?30:127);}else{p=k==0?&level:k==1?&fade:&decay;*p=clamp(*p+d,k==1?1:0,k==1?8:127);}changed=1;}if(changed){request=(unsigned)root|((unsigned)preset<<4)|((unsigned)playing<<8);screen();}led_button(BTN_PLAY,playing);for(int k=0;k<KEY_COUNT;k++)led_key(k,playing&&(KEY_FIRST_NOTE+k)%12==root);}
